<?php
namespace Tests\Feature;
use App\Models\AdminResourceViewState;use App\Models\Device;use App\Models\Organization;use App\Models\ResourceRevision;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
final class AdminViewedIndicatorsTest extends TestCase{use RefreshDatabase;
 private function users():array{$o=Organization::create(['name'=>'Viewed Org','slug'=>'viewed-org'.uniqid()]);$a=User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','platform_role'=>'platform_admin','status'=>'active']);$b=User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','platform_role'=>'platform_admin','status'=>'active']);$s=User::factory()->create(['organization_id'=>$o->id,'role'=>'owner','status'=>'active']);return[$o,$a,$b,$s];}
 public function test_view_is_explicit_personal_idempotent_and_gets_do_not_mark():void{[$o,$a,$b,$staff]=$this->users();$d=$this->actingAs($staff)->postJson('/api/devices',['name'=>'Pump','type'=>'sensor','serialNumber'=>'VIEW-1','protocol'=>'mqtt'])->assertCreated()->json('id');$this->actingAs($a)->getJson('/api/admin/resources/inventory/device/'.$d)->assertOk();$this->actingAs($a)->getJson('/api/admin/resources/inventory')->assertOk()->assertJsonPath('data.0.viewState','not_viewed');$this->assertSame(0,AdminResourceViewState::count());$first=$this->actingAs($a)->postJson('/api/admin/resources/inventory/device/'.$d.'/viewed',['admin_user_id'=>$b->id,'viewed_at'=>'2000-01-01','status'=>'reviewed'])->assertOk()->assertJsonPath('data.viewState','viewed')->json('data.firstViewedAt');$this->travel(1)->minutes();$this->actingAs($a)->postJson('/api/admin/resources/inventory/device/'.$d.'/viewed')->assertOk()->assertJsonPath('data.firstViewedAt',$first);$this->assertSame(1,AdminResourceViewState::count());$this->actingAs($a)->getJson('/api/admin/recently-created')->assertJsonPath('data.0.viewState','viewed');$this->actingAs($b)->getJson('/api/admin/resources/inventory')->assertJsonPath('data.0.viewState','not_viewed');$this->actingAs($staff)->postJson('/api/admin/resources/inventory/device/'.$d.'/viewed')->assertForbidden();$this->actingAs($a)->postJson('/api/admin/resources/inventory/device/999999/viewed')->assertNotFound();$this->assertSame((int)$a->id,(int)AdminResourceViewState::firstOrFail()->admin_user_id);}
 public function test_new_meaningful_revision_changes_only_personal_indicator_until_viewed_again():void{[$o,$admin,,$staff]=$this->users();$id=$this->actingAs($staff)->postJson('/api/devices',['name'=>'Pump','type'=>'sensor','serialNumber'=>'VIEW-2','protocol'=>'mqtt'])->assertCreated()->json('id');$this->actingAs($admin)->postJson('/api/admin/resources/inventory/device/'.$id.'/viewed')->assertOk();$before=Device::findOrFail($id)->created_at;$this->actingAs($staff)->patchJson('/api/devices/'.$id,['name'=>'Pump Updated'])->assertOk();$revision=ResourceRevision::where(['resource_type'=>'device','resource_id'=>$id])->latest('revision_number')->firstOrFail();$this->actingAs($admin)->getJson('/api/admin/resources/inventory')->assertJsonPath('data.0.viewState','updated_since_view');$this->actingAs($admin)->getJson('/api/admin/recently-updated')->assertJsonPath('data.0.viewState','updated_since_view')->assertJsonPath('data.0.revision.id',(string)$revision->id);$this->actingAs($admin)->postJson('/api/admin/resources/inventory/device/'.$id.'/viewed')->assertOk()->assertJsonPath('data.viewState','viewed');$this->actingAs($admin)->getJson('/api/admin/recently-updated')->assertJsonPath('data.0.viewState','viewed');$this->assertTrue(Device::findOrFail($id)->created_at->equalTo($before));$this->assertSame(2,ResourceRevision::where(['resource_type'=>'device','resource_id'=>$id])->count());}
 public function test_location_only_runtime_and_lifecycle_changes_do_not_create_updated_since_view():void{[$o,$admin,,$staff]=$this->users();$id=$this->actingAs($staff)->postJson('/api/devices',['name'=>'Pump','type'=>'sensor','serialNumber'=>'VIEW-3','protocol'=>'mqtt'])->assertCreated()->json('id');$this->actingAs($staff)->patchJson('/api/devices/'.$id,['name'=>'Meaningful'])->assertOk();$this->actingAs($admin)->postJson('/api/admin/resources/inventory/device/'.$id.'/viewed')->assertOk();Device::whereKey($id)->update(['last_seen'=>now(),'status'=>'offline']);$this->actingAs($admin)->postJson('/api/admin/resources/device/'.$id.'/lifecycle/disable')->assertOk();$this->actingAs($admin)->getJson('/api/admin/resources/inventory')->assertJsonPath('data.0.viewState','viewed')->assertJsonPath('data.0.lifecycle','disabled');}
}